def getAncestors(n: int, edges: list[list[int]]) -> list[list[int]]:
    from collections import defaultdict
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
    ans = [[] for _ in range(n)]
    def dfs(curr, ancestor, visited):
        for nxt in adj[curr]:
            if nxt not in visited:
                visited.add(nxt)
                ans[nxt].append(ancestor)
                dfs(nxt, ancestor, visited)
    for i in range(n):
        dfs(i, i, set())
    return [sorted(anc) for anc in ans]

